const validate = function validateReadOnlySql(plan, config = {}) {
  const requested = String(plan?.sql || '').trim();
  const maxRows = Math.max(1, Math.min(Number(config.max_rows || 500), 5000));
  const allowedSchemas = (config.allowed_schemas || ['public']).map((v) => String(v).toLowerCase());
  const allowedTables = (config.allowed_tables || []).map((v) => String(v).toLowerCase());
  const fail = (reason) => ({ allowed: false, reason, sql: null, params: [], output_format: plan?.output_format || 'json' });
  if (!requested) return fail('The model returned an empty SQL statement.');
  if (/--|\/\*/.test(requested)) return fail('SQL comments are not allowed.');
  const withoutTrailing = requested.replace(/;+\s*$/, '');
  if (withoutTrailing.includes(';')) return fail('Only one SQL statement is allowed.');
  if (!/^\s*(select|with)\b/i.test(withoutTrailing)) return fail('Only SELECT or WITH queries are allowed.');
  const scrubbed = withoutTrailing.replace(/'(?:''|[^'])*'/g, "''").replace(/\"(?:\"\"|[^\"])*\"/g, '""');
  const blocked = /\b(insert|update|delete|merge|drop|alter|truncate|create|replace|grant|revoke|copy|call|do|vacuum|analyze|refresh|reindex|cluster|listen|notify|lock)\b|\bfor\s+(update|share)\b|\binto\s+(temp|temporary|unlogged|[a-z_])/i;
  if (blocked.test(scrubbed)) return fail('A write, DDL, locking, or administrative keyword was detected.');
  if (/\b(pg_sleep|dblink|lo_import|lo_export|pg_read_file|pg_ls_dir|pg_stat_file|set_config)\s*\(/i.test(scrubbed)) return fail('A blocked PostgreSQL function was detected.');
  const cteNames = new Set([...scrubbed.matchAll(/(?:\bwith\b|,)\s*([a-z_][\w$]*)\s+as\s*\(/gi)].map((m) => m[1].toLowerCase()));
  const references = [...scrubbed.matchAll(/\b(?:from|join)\s+((?:[a-z_][\w$]*\.)?[a-z_][\w$]*)/gi)].map((m) => m[1].toLowerCase());
  for (const reference of references) {
    if (cteNames.has(reference)) continue;
    const parts = reference.split('.');
    const schema = parts.length === 2 ? parts[0] : 'public';
    const table = parts.length === 2 ? parts[1] : parts[0];
    if (!allowedSchemas.includes(schema)) return fail(`Schema ${schema} is not allowlisted.`);
    if (allowedTables.length && !allowedTables.includes(table) && !allowedTables.includes(reference)) return fail(`Table ${reference} is not allowlisted.`);
  }
  if (!references.length) return fail('No table reference was found.');
  let sql = withoutTrailing;
  const limitMatch = sql.match(/\blimit\s+(\d+)\s*$/i);
  if (limitMatch) {
    const requestedLimit = Number(limitMatch[1]);
    if (requestedLimit > maxRows) sql = sql.replace(/\blimit\s+\d+\s*$/i, `LIMIT ${maxRows}`);
  } else {
    sql = `${sql}\nLIMIT ${maxRows}`;
  }
  const params = Array.isArray(plan?.params) ? plan.params : [];
  return {
    allowed: true,
    reason: null,
    sql,
    params,
    explanation: String(plan?.explanation || ''),
    output_format: String(plan?.output_format || 'json').toLowerCase(),
    chart: plan?.chart || null,
  };
}; const data=$input.first().json; const result=validate(data.plan,data.guardrails); return [{json:{...data,validation:result}}];
